/** Coin images for launch-on-post: from the post, generated by your OpenAI key, or your own file. */
import { readFile } from "node:fs/promises";
import { basename, extname } from "node:path";
import type { LaunchInput } from "./pumpfun.js";
import { endpoints } from "../endpoints.js";

type Img = LaunchInput["image"];
const MAX = 4_500_000;

export async function imageFromUrl(url: string): Promise<Img> {
  if (!/^https:\/\//.test(url)) throw new Error("Image URL must be https.");
  const r = await fetch(url, { signal: AbortSignal.timeout(10_000) });
  const mime = (r.headers.get("content-type") ?? "").split(";")[0];
  if (!r.ok || !/^image\/(png|jpeg|gif|webp)$/.test(mime)) throw new Error(`Couldn't fetch the post image (${r.status} ${mime || "unknown type"}).`);
  const bytes = new Uint8Array(await r.arrayBuffer());
  if (bytes.length > MAX) throw new Error("Post image is over 4.5 MB.");
  return { bytes, mime, filename: `post.${mime.split("/")[1]}` };
}

/** A local file path, or a data: URL (an image uploaded in the panel and synced to the agent). */
export async function imageFromFile(path: string): Promise<Img> {
  const d = path.match(/^data:(image\/(?:png|jpeg|gif|webp));base64,(.+)$/);
  if (d) {
    const bytes = new Uint8Array(Buffer.from(d[2], "base64"));
    if (bytes.length > MAX) throw new Error("Default image is over 4.5 MB.");
    return { bytes, mime: d[1], filename: `image.${d[1].split("/")[1]}` };
  }
  const ext = extname(path).slice(1).toLowerCase();
  const mime = `image/${ext === "jpg" ? "jpeg" : ext}`;
  if (!/^image\/(png|jpeg|gif|webp)$/.test(mime)) throw new Error("Default image must be PNG, JPG, GIF or WebP.");
  const bytes = new Uint8Array(await readFile(path));
  if (bytes.length > MAX) throw new Error("Default image is over 4.5 MB.");
  return { bytes, mime, filename: basename(path) };
}

/** Generates a square coin image with OpenAI's image API (needs OPENAI_API_KEY in your keystore). */
export async function generateImage(prompt: string, openaiKey: string): Promise<Img> {
  const r = await fetch(endpoints.openaiImages(), {
    method: "POST",
    headers: { Authorization: `Bearer ${openaiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({ model: "gpt-image-1", prompt, size: "1024x1024", n: 1 }),
    signal: AbortSignal.timeout(60_000),
  });
  const j = (await r.json().catch(() => ({}))) as { data?: Array<{ b64_json?: string }>; error?: { message?: string } };
  const b64 = j.data?.[0]?.b64_json;
  if (!r.ok || !b64) throw new Error(`Image generation failed: ${j.error?.message ?? r.status}`);
  return { bytes: new Uint8Array(Buffer.from(b64, "base64")), mime: "image/png", filename: "generated.png" };
}
